class ExportManager::Template::Master::Vendors::VendorLocations < ExportManager::Builders::Template
  label 'Vendor Locations'
  description 'Vendor Locations Export'
  export_format 'xls'
  resource 'vendor_locations'
  subscribe 'vendor_locations'
  default true

  form_custom_fields :vendors, template_prefix: 'record.vendor'

  attribute :vendor_business_name, template: '{{ record.vendor.business_name }}'
  attribute :vendor_trade_name, template: '{{ record.vendor.trade_name }}'
  attribute :vendor_id, template: '{{ record.vendor.vendor_id }}'
  attribute :name, template: '{{ record.vendor.name }}'
  attribute :msme_registered, template: '{{ record.vendor.msme_registered }}'
  attribute :msme_registration_number, template: '{{ record.vendor.msme_registration_number }}'
  attribute :mobile_number, template: '{{ record.vendor.mobile_number }}'
  attribute :email, template: '{{ record.vendor.email }}'
  attribute :created_by, template: '{{ record.vendor.created_by.name }}'
  attribute :pan, template: '{{ record.vendor.pan }}'
  attribute :poc_name, template: '{{ record.poc_name }}'
  attribute :poc_email, template: '{{ record.poc_email }}'
  attribute :gstin_location_address, template: '{{ record.address }}'
  attribute :gstin, template: '{{ record.gstin }}'
  attribute :tds_percentage, template: ''
  attribute :state_code, template: '{{ record.vendor.state_code.name }} - {{ record.vendor.state_code.code }}'
  attribute :description, template: '{{ record.vendor.description }}'
  attribute :vendor_type, template: '{{ record.vendor.vendor_type.name }}'
  attribute :default_account_number, template: '{{ record.vendor.bank_accounts.first.account_number }}'
  attribute :default_account_name, template: '{{ record.vendor.bank_accounts.first.name }}'
  attribute :default_account_ifsc, template: '{{ record.vendor.bank_accounts.first.ifsc }}'
  attribute :second_account_number, template: '{{ record.vendor.bank_accounts.second.account_number }}'
  attribute :second_account_name, template: '{{ record.vendor.bank_accounts.second.name }}'
  attribute :second_account_ifsc, template: '{{ record.vendor.bank_accounts.second.ifsc }}'
  attribute :third_account_number, template: '{{ record.vendor.bank_accounts.third.account_number }}'
  attribute :third_account_name, template: '{{ record.vendor.bank_accounts.third.name }}'
  attribute :third_account_ifsc, template: '{{ record.vendor.bank_accounts.third.ifsc }}'
  attribute :fourth_account_number, template: '{{ record.vendor.bank_accounts.fourth.account_number }}'
  attribute :fourth_account_name, template: '{{ record.vendor.bank_accounts.fourth.name }}'
  attribute :fourth_account_ifsc, template: '{{ record.vendor.bank_accounts.fourth.ifsc }}'
  attribute :created_at, template: "{{ record.vendor.created_at | date: '%d-%b-%Y' }}"
  attribute :active, template: '{% if record.vendor.deactivated %}FALSE{% else %}TRUE{% endif %}'
end
